const labels: Record<string, string> = {
  saved: "原件已保存",
  queued: "等待解析",
  running: "正在解析",
  leased: "正在准备",
  retry_wait: "等待重试",
  failed: "解析失败，原件仍保留",
  parsed: "解析完成",
  cancelled: "已取消",
};
async function load() {
  clearTimeout(timer);
  try {
    const result = await api<Item[]>("/document-imports");
    if (!stopped) {
      items.value = result;
      error.value = "";
    }
  } catch (e) {
    if (!stopped) error.value = String(e);
  } finally {
    if (!stopped) timer = setTimeout(() => void load(), 3000);
  }
}
async function download(item: Item) {
  try {
    const r = await fetch(
      "/api/document-imports/" + encodeURIComponent(item.id) + "/original",
      { headers: headers() },
    );
    if (!r.ok) throw Error("原件读取失败");
    const blob = await r.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = item.name;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  } catch (e) {
    error.value = String(e);
  }
}
onMounted(() => void load());
onBeforeUnmount(() => {
  stopped = true;
  clearTimeout(timer);
});
</script>
<template>
  <OmDisclosure
    v-if="items.length || error"
    title="文档导入记录"
    :default-open="true"
    class="imports"
  >
    <p class="muted">
      原文件上传后即保存。解析失败或服务重启后，可以继续处理，不必重新上传。
    </p>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <article v-for="item in items" :key="item.id">
      <h3>{{ item.name }}</h3>
      <p>{{ labels[item.state] ?? item.state }}</p>
      <p v-if="item.error" class="error">{{ item.error }}</p>
      <div class="actions">
        <OmButton
          v-if="item.revisionId"
          variant="secondary"
          @click="emit('open', item.revisionId)"
          >阅读材料</OmButton
        ><OmButton variant="ghost" @click="download(item)"
          >下载保存的原件</OmButton
        >
      </div>
      <ReprocessControls
        target="document"
        :target-id="item.id"
        :title="item.name"
        :actions="['parse']"
      />

private async parse(job: JobLease, signal: AbortSignal) {
  const ref = job.inputRefs[0] as {
    importId: string;
    originalAssetId: string;
    name: string;
    externalId: string;
    selection: ImportSelection;
  };
  const current = () =>
    this.store.db
      .prepare(
        "SELECT original_asset_id,job_id FROM document_imports WHERE id=?",
      )
      .get(ref.importId);
  if (current()?.job_id !== job.id) return { usage: { superseded: true } };
  const bytes = this.store.asset(ref.originalAssetId);
  if (!bytes)
    throw new JobExecutionError(
      "保存的文档原件不可用，请挂载冷存储或恢复备份",
      "config",
    );
  try {
    const input: CaptureInput = await (this.options.parser ?? documentInput)(
      bytes,
      ref.name,
      this.store.dataDir,
      ref.externalId,
    );
    if (signal.aborted)
      throw new JobExecutionError("文档解析已中断，原件仍保留", "transient");
    if (
      current()?.job_id !== job.id ||
      current()?.original_asset_id !== ref.originalAssetId
    )
      return { usage: { superseded: true } };
    const captured = this.store.capture(input, {
      ...ref.selection,
      learning: false,
    });
    const learningJob =
      this.options.learningEnabled !== false &&
      ref.selection.learning !== false
        ? this.store.jobs.enqueue({
            kind: "extract_claims",
            inputRefs: [
              {
                sourceId: captured.revision.sourceId,
                revisionId: captured.revision.id,
                validityEpoch: Number(
                  this.store.db
                    .prepare(
                      "SELECT validity_epoch FROM source_state WHERE source_id=?",
                    )
                    .get(captured.revision.sourceId)!.validity_epoch,
                ),
                documentParseJobId: job.id,
              },
            ],
            roleVersion: "extractor@1",
            policyVersion: "memory-policy@1",
            cause: "reparse_saved_original",
            parentJobId: job.id,
          }).job
        : null;
    this.store.db
      .prepare(
        "UPDATE document_imports SET state='parsed',revision_id=?,error=NULL,updated_at=? WHERE id=? AND job_id=?",
      )
      .run(
        captured.revision.id,
        new Date().toISOString(),
        ref.importId,
        job.id,
      );
    return {
      resultRef: captured.revision.id,
      usage: { learningJobId: learningJob?.id ?? null },
    };

this.db
  .prepare("UPDATE sources SET head=? WHERE id=?")
  .run(revisionId, String(source.id));
this.db
  .prepare(
    `INSERT INTO source_state(
       source_id,workspace_id,registered_scope,head_revision_id,
       validity_epoch,capture_policy,updated_at
     ) VALUES(?,'personal','{}',?,1,'{}',?)
     ON CONFLICT(source_id) DO UPDATE SET
       head_revision_id=excluded.head_revision_id,
       validity_epoch=source_state.validity_epoch+1,
       updated_at=excluded.updated_at`,
  )
  .run(String(source.id), revisionId, now());
if (head) {
  this.db
    .prepare(
      `UPDATE memory_dependencies SET state='stale'
       WHERE source_id=? AND source_revision_id<>?`,
    )
    .run(String(source.id), revisionId);
  this.db
    .prepare(
      `UPDATE memories SET status='invalidated',updated_at=?
       WHERE head_revision_id IN (
         SELECT memory_revision_id FROM memory_dependencies
         WHERE source_id=? AND state='stale'
       )`,
    )
    .run(now(), String(source.id));
  recordSourceRefresh(this.db, "personal", [
    {
      sourceId: String(source.id),
      previousRevisionId: String(head.id),
      revisionId,
    },
  ]);
  if (selection.learning !== false)
    this.jobs.enqueueInCurrentTransaction({
      kind: "refresh_dependents",
      inputRefs: [
        {
          sourceId: String(source.id),
          previousRevisionId: String(head.id),
          revisionId,
        },
      ],
      roleVersion: "deterministic@1",
      policyVersion: "memory-policy@1",
      cause: "source_update",
    });

private record(row: Row) {
  const input = reprocessingInput.parse(JSON.parse(String(row.payload)));
  const root = this.store.jobs.get(String(row.job_id));
  const children = this.store.db
    .prepare(
      `WITH RECURSIVE descendants(id) AS (
    SELECT value FROM json_each(?) UNION SELECT j.id FROM jobs j JOIN descendants d ON j.parent_job_id=d.id
  ) SELECT j.id FROM jobs j JOIN descendants d ON j.id=d.id`,
    )
    .all(String(row.children))
    .map((r) => this.store.jobs.get(String(r.id)))
    .filter((j) => !!j);
  const unfinished = children.find((j) => active.has(j.state));
  const failed = children.find((j) =>
    ["failed", "cancelled", "awaiting_decision"].includes(j.state),
  );
  const state =
    root && active.has(root.state)
      ? root.state
      : root?.state !== "succeeded"
        ? (root?.state ?? "failed")
        : unfinished
          ? "running"
          : (failed?.state ?? "succeeded");
  const title =
    input.target === "article"
      ? this.store.db
          .prepare(
            "SELECT json_extract(plan,'$.title') AS title FROM knowledge_pages WHERE document_key=?",
          )
          .get(input.targetId)?.title
      : input.target === "document"
        ? this.store.db
            .prepare("SELECT name AS title FROM document_imports WHERE id=?")
            .get(input.targetId)?.title
        : input.target === "message"
          ? this.store.db
              .prepare(
                "SELECT chat_name AS title FROM personal_lark_messages WHERE id=?",
              )
              .get(input.targetId)?.title
          : this.store.db
              .prepare(
                "SELECT r.title FROM revisions r JOIN sources s ON s.head=r.id WHERE s.id=? OR r.id=?",
              )
              .get(input.targetId, input.targetId)?.title;
  return {
    ...input,
    id: String(row.id),
    title: title
      ? String(title)
      : input.target === "bot-event"
        ? "机器人消息"
        : "保存的材料",
    jobId: String(row.job_id),
    state,
    error: failed?.lastError ?? root?.lastError ?? null,
    result: row.result
      ? (JSON.parse(String(row.result)) as OperationResult)
      : null,
    jobs: children.map((j) => ({
      id: j.id,
      kind: j.kind,
      state: j.state,
      error: j.lastError,
    })),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };

const names: Record<string, string> = {
  document_parse: "解析文档",
  lark_inbound: "保存机器人消息资源",
  "material:reprocess": "重新处理材料",
  extract_claims: "提炼记忆",
  verify_proposals: "核验候选记忆",
  refresh_dependents: "复查受影响记忆",
  knowledge_analyze: "分析材料",
  knowledge_synthesize: "整理知识正文",
};
const materialJobs = computed(() =>
  props.jobs.filter((j) => j.kind !== "scheduled_task"),
);
const waiting = computed(
  () => materialJobs.value.filter((j) => j.state === "queued").length,
);
const filtered = computed(() =>
  materialJobs.value.filter(
    (j) =>
      filter.value === "all" ||
      (filter.value === "queued"
        ? j.state === "queued"
        : filter.value === "failed"
          ? ["failed", "retry_wait"].includes(j.state)
          : j.state !== "queued"),
  ),
);
function title(job: Job) {
  return (
    job.materialTitle ||
    props.sources.find((s) =>
      job.inputRefs.some(
        (r) => r.sourceId === s.sourceId || r.revisionId === s.id,
      ),
    )?.title ||
    names[job.kind] ||
    "材料处理"
  );
}
function outcome(job: Job) {
  const results = jobProposals(job);
  if (job.contextQuestion)
    return `${job.contextQuestion} 原文已保留，选择归属后会继续提炼记忆。`;
  if (job.state === "queued")
    return props.processing.enabled
      ? "已保存原文，等待后台处理。尚未调用模型。"
      : "自动处理未启用，原文已经保存；此任务还没有调用模型。";
  if (job.state === "succeeded")
    return results.length
      ? `形成 ${results.length} 条候选记忆，其中 ${results.filter((p) => p.state === "applied").length} 条已应用。`
      : job.kind === "refresh_dependents"
        ? "已完成依赖检查；需要重新提炼的材料会进入后续任务。"
        : "此步骤已结束，没有直接关联的候选记忆。后续核验结果见对应任务。";
  if (job.state === "skipped")
    return "无需继续处理此任务，原材料仍可阅读与检索。";
  return "处理结果和候选记忆会显示在下方。";
}

const stateText: Record<string, string> = {
  queued: "等待处理",
  leased: "已领取",
  running: "正在处理",
  succeeded: "处理完成",
  skipped: "已跳过",
  awaiting_decision: "等待判断",
  retry_wait: "等待重试",
  failed: "处理失败",
  cancelled: "已取消",
  proposed: "候选",
  validating: "核验中",
  rejected: "已拒绝",
  approved: "已批准",
  applied: "已生效",
  stale: "已过期",
};
const tone = (state: string) =>
  ["failed", "rejected", "stale"].includes(state)
    ? "danger"
    : ["awaiting_decision", "retry_wait", "queued"].includes(state)
      ? "warning"
      : ["succeeded", "applied", "approved"].includes(state)

claimNext(input: {
  workerId: string;
  fingerprint: JobAttemptFingerprint;
  now?: Date;
  leaseMs?: number;
  kinds?: string[];
  jobIds?: string[];
}): JobLease | null {
  const now = input.now ?? new Date();
  const at = iso(now);
  const leaseMs = Math.max(100, input.leaseMs ?? 60_000);
  return this.transaction(() => {
    while (true) {
      const row = this.db
        .prepare(
          `SELECT * FROM jobs
           WHERE cancel_requested=0 ${input.kinds ? `AND kind IN (${input.kinds.map(() => "?").join(",")})` : ""} ${input.jobIds ? `AND id IN (${input.jobIds.map(() => "?").join(",")})` : ""} AND not_before<=? AND
             (state IN ('queued','retry_wait') OR
              (state IN ('leased','running') AND lease_expires_at<=?))
           ORDER BY not_before,created_at LIMIT 1`,
        )
        .get(...(input.kinds ?? []), ...(input.jobIds ?? []), at, at) as
        | Row
        | undefined;
      if (!row) return null;
      const job = fromRow(row);
      if (job.state === "leased" || job.state === "running")
        this.db
          .prepare(
            `UPDATE job_attempts SET ended_at=?,outcome='lease_expired',
               error_kind='transient',error='Lease expired before completion'
             WHERE job_id=? AND attempt=? AND ended_at IS NULL`,
          )
          .run(at, job.id, job.attempt);
      const generationAttempts = Number(
        (
          this.db
            .prepare(
              "SELECT count(*) AS count FROM job_attempts WHERE job_id=? AND generation=?",
            )
            .get(job.id, job.generation) as { count: number }
        ).count,
      );
      if (generationAttempts >= job.maxAttempts) {
        this.db
          .prepare(
            `UPDATE jobs SET state='failed',error_kind='attempt_limit',
               last_error='Attempt limit reached',finished_at=?,updated_at=?,
               lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE id=?`,
          )
          .run(at, at, job.id);
        continue;

fail(input: {
  jobId: string;
  leaseToken: string;
  kind: JobFailureKind;
  message: string;
  usage?: Record<string, unknown>;
  now?: Date;
  retryBaseMs?: number;
}) {
  const now = input.now ?? new Date();
  const at = iso(now);
  return this.transaction(() => {
    const row = this.db
      .prepare("SELECT * FROM jobs WHERE id=?")
      .get(input.jobId) as Row | undefined;
    if (
      !row ||
      row.lease_token !== input.leaseToken ||
      !["leased", "running"].includes(String(row.state))
    )
      throw Error("STALE_JOB_LEASE");
    const job = fromRow(row);
    const kind = job.cancelRequested ? "cancelled" : input.kind;
    const message = publicError(input.message);
    this.db
      .prepare(
        `UPDATE job_attempts SET ended_at=?,outcome=?,error_kind=?,error=?,usage=?
         WHERE job_id=? AND attempt=? AND ended_at IS NULL`,
      )
      .run(
        at,
        kind === "cancelled" ? "cancelled" : "failed",
        kind,
        message,
        JSON.stringify(input.usage ?? {}),
        input.jobId,
        job.attempt,
      );
    const kindCount = Number(
      (
        this.db
          .prepare(
            `SELECT count(*) AS count FROM job_attempts
             WHERE job_id=? AND generation=? AND error_kind=?`,
          )
          .get(input.jobId, job.generation, kind) as { count: number }
      ).count,
    );
    const generationCount = Number(
      (
        this.db
          .prepare(
            "SELECT count(*) AS count FROM job_attempts WHERE job_id=? AND generation=?",
          )
          .get(input.jobId, job.generation) as { count: number }
      ).count,
    );
    const retryLimit =
      kind === "bad_output" ? 2 : kind === "transient" ? 3 : 0;
    const retry =
      retryLimit > 0 &&
      kindCount < retryLimit &&
      generationCount < job.maxAttempts;
    const next = retry
      ? "retry_wait"
      : kind === "cancelled"
        ? "cancelled"
        : "failed";
    const delay =
      Math.max(0, input.retryBaseMs ?? 1000) *
      2 ** Math.max(0, kindCount - 1);
    const notBefore = retry ? iso(new Date(now.getTime() + delay)) : at;
    this.db
      .prepare(
        `UPDATE jobs SET state=?,not_before=?,last_error=?,error_kind=?,
           finished_at=?,updated_at=?,lease_owner=NULL,lease_token=NULL,
           lease_expires_at=NULL,cancel_requested=CASE WHEN ?='cancelled' THEN 1 ELSE cancel_requested END
         WHERE id=?`,
      )
      .run(
        next,
        notBefore,
        message,
        kind,
        retry ? null : at,
        at,
        next,
        input.jobId,
      );
    return this.get(input.jobId)!;

