/** A new user instruction schedules the next step on the existing checkout.
 * Old jobs and their attempts remain available; external inputs stay frozen. */
continueTask(
  id: string,
  actor: WorkActor,
  reviewedFingerprint?: string,
  automatic = false,
) {
  const task = this.read(id);
  if (task.principalId !== actor.principalId)
    throw Error("不能操作其他人的编码任务");
  if (active.has(task.job.state)) {
    if (reviewedFingerprint) throw Error("任务仍在运行，请等待当前操作完成");
    this.store.db
      .prepare(
        "INSERT OR REPLACE INTO assistant_development_updates VALUES(?,?)",
      )
      .run(id, JSON.stringify(actor));
    this.store.db
      .prepare("UPDATE assistant_development SET message=? WHERE id=?")
      .run(
        "已保存继续执行的交办；当前阶段结束后保留副本并核对最新需求。",
        id,
      );
    return this.read(id);
  }
  if (reviewedFingerprint) {
    if (
      task.run?.state !== "ready" ||
      task.run.reviewedFingerprint !== reviewedFingerprint
    )
      throw Error("请先读取当前评审结果，再应用同一份补丁");
  } else {
    if (!this.profile) throw Error("尚未配置编码 Agent");
    if (task.run?.state === "applied")
      throw Error("任务已应用到登记仓库；后续变更需从更新后的仓库交办新任务");
    if (task.run?.state === "ready") {
      const update = inspectRequirementChange(
        this.pages.repository,
        task.run,
      );
      if (!update) throw Error("任务已完成且需求未变化，可直接查看结果");
    }
  }
  this.store.tx(() => {
    const prior = task.job.inputRefs[0] as DevelopmentJobInput;
    const { job } = this.store.jobs.enqueueInCurrentTransaction({
      kind,
      inputRefs: [
        {
          taskId: id,
          capabilities: prior.capabilities,
          handoff: prior.handoff,
          profiles: task.run?.profiles ?? prior.profiles,
          project: task.run?.project ?? prior.project,
          operation: reviewedFingerprint ? "apply" : "develop",
          reviewedFingerprint,
          continuation: automatic ? undefined : actor,
          replan: !reviewedFingerprint,
        },
      ],
      roleVersion: "coding-and-review@1",
      policyVersion: "owner-delegated@1",
      // Filesystem application failures need a fresh owner request after the
      // source is fixed, rather than repeatedly retrying a possibly applied patch.
      maxAttempts: reviewedFingerprint ? 1 : 30,
      cause: `owner-${reviewedFingerprint ? "apply" : "resume"}:${actor.requestId}`,
    });
    this.store.db
      .prepare(
        "UPDATE assistant_development SET job_id=?,notified=0,message=? WHERE id=?",
      )
      .run(
        job.id,
        reviewedFingerprint
          ? "已安排应用这份已评审补丁；后台将再次核对需求与仓库状态，目前尚未应用。"
          : "已安排继续原编码任务，保留副本与已选资料；最新需求复核完成后对比变化，调整实现并独立评审。",
        id,

private reconcileChanges() {
  if (!this.profile) return;
  // Refresh applicability only when a delegated task could continue.
  const candidates = this.list().flatMap((task) => {
    const run = task.run;
    if (
      active.has(task.job.state) ||
      task.job.state === "cancelled" ||
      !run ||
      run.state === "applied"
    )
      return [];
    const pending = this.store.db
      .prepare(
        "SELECT actor FROM assistant_development_updates WHERE task_id=?",
      )
      .get(task.id);
    if (!pending && !this.pages.maintenance.status(task.key)?.enabled)
      return [];
    return [{ task, run, pending }];
  });
  if (!candidates.length) return;
  this.pages.repository.refresh();
  for (const { task, run, pending } of candidates) {
    try {
      const current = this.pages.repository.get(task.key);
      if (!current?.current) continue;
      if (
        !pending &&
        (!this.pages.maintenance.status(task.key)?.enabled ||
          current.revision === run.requirementRevision)
      )
        continue;
      const update = inspectRequirementChange(
        this.pages.repository,
        run,
      );
      if (!update && run.state === "ready") {
        if (pending)
          this.store.db
            .prepare(
              "DELETE FROM assistant_development_updates WHERE task_id=?",
            )
            .run(task.id);
        continue;
      }
      if (!update && !pending) continue;
      const actor: WorkActor = pending
        ? JSON.parse(String(pending.actor))
        : {
            requestId: `requirement-change:${task.id}:${current.revision}`,
            conversationId: task.conversationId,
            principalId: task.principalId,
            visibility: "private",
            userText:
              run.handoff?.assignment.text ?? "继续已交办的需求实现",
          };
      this.continueTask(task.id, actor, undefined, !pending);

/** Describe a real change; the coding agent interprets its impact together with
 * the original assignment and current code, without another planning model. */
export function inspectRequirementChange(
  repository: KnowledgeRepository,
  run: {
    requirementKey: string;
    requirementRevision: string;
    requirementBasis?: RequirementBasis;
  },
) {
  repository.refresh();
  const previous = repository.get(run.requirementKey, run.requirementRevision);
  const current = repository.get(run.requirementKey);
  if (
    !previous?.document.requirement ||
    !current?.document.requirement ||
    !current.current
  )
    throw Error("等待最新需求完成调查与复核；保留当前代码");
  const basis = requirementBasis(repository, current);
  if (
    run.requirementBasis &&
    stableDigest(basis) === stableDigest(run.requirementBasis)
  )
    return null;
  if (!run.requirementBasis && current.revision === run.requirementRevision)
    return null;
  const before = previous.document.requirement,
    after = current.document.requirement;
  const old = new Map(before.criteria.map((c) => [c.id, c.description]));
  const next = new Map(after.criteria.map((c) => [c.id, c.description]));
  const inputs = new Map(
    (run.requirementBasis?.inputs ?? []).map((m) => [m.key, m.digest]),
  );
  const latest = new Map(basis.inputs.map((m) => [m.key, m.digest]));
  const change: RequirementChange = {
    at: new Date().toISOString(),
    fromRevision: previous.revision,
    toRevision: current.revision,
    before,
    after,
    criteria: {
      added: [...next.keys()].filter((k) => !old.has(k)),
      removed: [...old.keys()].filter((k) => !next.has(k)),
      changed: [...next.keys()].filter(
        (k) => old.has(k) && old.get(k) !== next.get(k),
      ),
      retained: [...next.keys()].filter((k) => old.get(k) === next.get(k)),
    },
    materials: [...new Set([...inputs.keys(), ...latest.keys()])]
      .filter((k) => inputs.get(k) !== latest.get(k))
      .map((key) => ({
        key,
        before: inputs.get(key) ?? null,
        after: latest.get(key) ?? null,
      })),
    planChanged: run.requirementBasis?.plan !== basis.plan,
  };
  return { article: current, basis, change };

function definition(article: KnowledgeArticle) {
  const r = article.document.requirement;
  // Status/evidence/action progress may change after execution. The original
  // objective, exclusions and acceptance conditions still constrain this run.
  return stableDigest(
    r && {
      objective: r.objective,
      nonGoals: [...r.nonGoals].sort(),
      criteria: r.criteria
        .map((c) => ({ id: c.id, description: c.description }))
        .sort((a, b) => a.id.localeCompare(b.id)),
    },
  );
}

export function requirementBasis(
  repository: KnowledgeRepository,
  article: KnowledgeArticle,
): RequirementBasis {
  ensureDevelopmentResults(repository.store);
  const plan = repository
    .pages()
    .find((p) => p.key === article.document.key)?.plan;
  if (!plan) throw Error("需求计划不存在");
  // Registered execution results and the page's host-attached task/run state
  // describe progress. Including the latter would invalidate a review when the
  // review itself changes the run state. Ordinary source updates remain inputs.
  const reports = new Set(
    repository.store.db
      .prepare(
        "SELECT source_id FROM development_results WHERE requirement_key=?",
      )
      .all(article.document.key)
      .map((row) => String(row.source_id)),
  );
  for (const row of repository.store.db
    .prepare(
      "SELECT source_id FROM knowledge_page_inputs WHERE document_key=? AND purpose='followup-state'",
    )
    .all(article.document.key))
    reports.add(String(row.source_id));
  const inputs = new Map(
    repository
      .materialsForPlan(plan)
      .filter((m) => !reports.has(m.sourceId))
      .map((m) => [m.key, m.digest]),
  );
  const selection = stableDigest([...inputs.keys()].sort());
  // Background actually cited by the frozen article can be outside its initial
  // selection. Follow it to original materials, including derived page inputs.
  const visit = (a: KnowledgeArticle, seen = new Set<string>()) => {
    if (seen.has(a.revision)) return;
    seen.add(a.revision);
    for (const d of a.dependencies) {
      if (d.kind === "material") {
        const current = repository.resolveMaterial(d.key)?.material;
        if (!current || !reports.has(current.sourceId))
          inputs.set(d.key, current?.digest ?? "missing");
      } else {
        const dependency = repository.get(d.key, d.digest);
        if (dependency) visit(dependency, seen);
      }
    }
  };
  visit(article);
  return {
    plan: stableDigest(plan),
    selection,
    inputs: [...inputs]
      .map(([key, digest]) => ({ key, digest }))
      .sort((a, b) => a.key.localeCompare(b.key)),
    definition: definition(article),
  };

  (run.continuations ??= []).push({
    ...options.continuation,
    at: new Date().toISOString(),
  });
  this.save(run);
}
