          .prepare(
            `UPDATE jobs SET state='failed',error_kind='attempt_limit',
               last_error='Attempt limit reached',finished_at=?,updated_at=?,
               lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE id=?`,
          )
          .run(at, at, job.id);
