    stage = "applied";
    label = "已更新记忆或事项";
  } else if (job.state === "succeeded") {
    stage = "read";
    label = "已阅读，本次没有新增记忆";
  }
}
if (item.state === "review" && !job) label = "已保存，部分内容待补读";
